import styles from "./AdrList.module.css";

export interface Adr {
  id: string;
  title: string;
}

/**
 * Discriminated union instead of an `isLoading` + `adrs` pair — a boolean
 * paired with data would let "loading" and "has adrs" be true at once,
 * a state the caller (fetching from .ai-state/decisions/) can never
 * legitimately produce.
 */
export type AdrListState =
  | { status: "loading" }
  | { status: "ready"; adrs: Adr[] };

const SKELETON_ROW_COUNT = 4;

export function AdrList({ state }: { state: AdrListState }) {
  if (state.status === "loading") {
    return <AdrListSkeleton />;
  }

  return (
    <ul>
      {state.adrs.map((adr) => (
        <li key={adr.id}>{adr.title}</li>
      ))}
    </ul>
  );
}

// Renders synchronously with the "loading" state — no timers or async
// gating here — so the caller controls the < 100ms budget simply by
// passing { status: "loading" } as the initial render state.
function AdrListSkeleton() {
  const rows = Array.from({ length: SKELETON_ROW_COUNT });

  return (
    <div className={styles.skeleton} role="status" aria-live="polite">
      <span className={styles.srOnly}>Loading decisions…</span>
      {rows.map((_, index) => (
        <div key={index} className={styles.skeletonRow} aria-hidden="true" />
      ))}
    </div>
  );
}

import type { CSSProperties } from "react";

export type Adr = { id: string; title: string };

// Discriminated union: a list is either still loading or has resolved adrs —
// never both at once, so no illegal "loading but here's stale data" state.
export type AdrListState =
  | { status: "loading" }
  | { status: "ready"; adrs: Adr[] };

const SKELETON_ROW_COUNT = 3;
const SKELETON_ROW_HEIGHT = "1.2em";

// Renders offscreen but still announced to assistive tech — keeps the
// skeleton visually silent while `aria-live` reads the loading state.
const VISUALLY_HIDDEN_STYLE: CSSProperties = {
  position: "absolute",
  width: 1,
  height: 1,
  padding: 0,
  margin: -1,
  overflow: "hidden",
  clip: "rect(0, 0, 0, 0)",
  whiteSpace: "nowrap",
  border: 0,
};

const SKELETON_ROW_STYLE: CSSProperties = {
  height: SKELETON_ROW_HEIGHT,
  margin: "var(--space-2) 0",
  borderRadius: "var(--radius-1)",
  background: "var(--color-skeleton)",
};

function AdrListSkeleton() {
  return (
    <ul aria-busy="true" aria-live="polite">
      <li style={VISUALLY_HIDDEN_STYLE}>Loading decisions…</li>
      {Array.from({ length: SKELETON_ROW_COUNT }, (_, index) => (
        <li key={index} style={SKELETON_ROW_STYLE} />
      ))}
    </ul>
  );
}

export function AdrList({ state }: { state: AdrListState }) {
  if (state.status === "loading") {
    return <AdrListSkeleton />;
  }

  return (
    <ul>
      {state.adrs.map((adr) => (
        <li key={adr.id}>{adr.title}</li>
      ))}
    </ul>
  );
}

import "../styles/AdrList.css";

interface Adr {
  id: string;
  title: string;
}

// Discriminated union: a list can't be simultaneously "loading" and holding
// stale `adrs`, so that illegal combination has no representation here.
type AdrListProps =
  | { status: "loading" }
  | { status: "ready"; adrs: Adr[] };

// Matches typical decision-record density per web-ui-design's skeleton
// guidance (3-5 rows) without implying a specific real count.
const SKELETON_ROW_COUNT = 3;

export function AdrList(props: AdrListProps) {
  if (props.status === "loading") {
    return (
      <ul aria-busy="true" aria-label="Loading decisions">
        {Array.from({ length: SKELETON_ROW_COUNT }, (_, index) => (
          <li key={index} className="adr-list-skeleton-row" />
        ))}
      </ul>
    );
  }

  return (
    <ul>
      {props.adrs.map((adr) => (
        <li key={adr.id}>{adr.title}</li>
      ))}
    </ul>
  );
}

